import{_ as r,a0 as p,w as s,s as u,ao as l,I as i,x as n,a1 as o,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"CentOS 8 安装图解 | LCTT x X-CMD","titleTemplate":false,"description":"CentOS 8 安装图解 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CentOS 8 安装图解 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CentOS 8 安装图解 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190927 CentOS 8 Installation Guide with Screenshots","title":"CentOS 8 安装图解","tag":"201910","desc":""},"relativePath":"201910/20190927 CentOS 8 Installation Guide with Screenshots.md","filePath":"[post].md"}'),c={name:"201910/20190927 CentOS 8 Installation Guide with Screenshots.md"};function d(w,t,h,S,m,C){const e=p("Link");return s(),u("div",null,[t[18]||(t[18]=l('<h1 id="centos-8-安装图解" tabindex="-1">CentOS 8 安装图解 <a class="header-anchor" href="#centos-8-安装图解" aria-label="Permalink to “CentOS 8 安装图解”">​</a></h1><p>继 RHEL 8 发布之后，CentOS 社区也发布了让人期待已久的 CentOS 8，并发布了两种模式：</p><ul><li>CentOS stream：滚动发布的 Linux 发行版，适用于需要频繁更新的开发者</li><li>CentOS：类似 RHEL 8 的稳定操作系统，系统管理员可以用其部署或配置服务和应用</li></ul><p>在这篇文章中，我们会使用图解的方式演示 CentOS 8 的安装方法。</p><h3 id="centos-8-的新特性" tabindex="-1">CentOS 8 的新特性 <a class="header-anchor" href="#centos-8-的新特性" aria-label="Permalink to “CentOS 8 的新特性”">​</a></h3><ul><li>DNF 成为了默认的软件包管理器，同时 yum 仍然是可用的</li><li>使用网络管理器（<code>nmcli</code> 和 <code>nmtui</code>）进行网络配置，移除了网络脚本</li><li>使用 Podman 进行容器管理</li><li>引入了两个新的包仓库：BaseOS 和 AppStream</li><li>使用 Cockpit 作为默认的系统管理工具</li><li>默认使用 Wayland 作为显示服务器</li><li><code>iptables</code> 将被 <code>nftables</code> 取代</li><li>使用 Linux 内核 4.18</li><li>提供 PHP 7.2、Python 3.6、Ansible 2.8、VIM 8.0 和 Squid 4</li></ul><h3 id="centos-8-所需的最低硬件配置" tabindex="-1">CentOS 8 所需的最低硬件配置: <a class="header-anchor" href="#centos-8-所需的最低硬件配置" aria-label="Permalink to “CentOS 8 所需的最低硬件配置:”">​</a></h3><ul><li>2 GB RAM</li><li>64 位 x86 架构、2 GHz 或以上的 CPU</li><li>20 GB 硬盘空间</li></ul><h3 id="centos-8-安装图解-1" tabindex="-1">CentOS 8 安装图解 <a class="header-anchor" href="#centos-8-安装图解-1" aria-label="Permalink to “CentOS 8 安装图解”">​</a></h3><h4 id="第一步-下载-centos-8-iso-文件" tabindex="-1">第一步：下载 CentOS 8 ISO 文件 <a class="header-anchor" href="#第一步-下载-centos-8-iso-文件" aria-label="Permalink to “第一步：下载 CentOS 8 ISO 文件”">​</a></h4>',10)),i("p",null,[t[1]||(t[1]=n("在 CentOS 官方网站 ",-1)),o(e,{href:"https://www.centos.org/download/"},{default:a(()=>[...t[0]||(t[0]=[n("https://www.centos.org/download/",-1)])]),_:1}),t[2]||(t[2]=n(" 下载 CentOS 8 ISO 文件。",-1))]),t[19]||(t[19]=l('<h4 id="第二步-创建-centos-8-启动介质-usb-或-dvd" tabindex="-1">第二步： 创建 CentOS 8 启动介质（USB 或 DVD） <a class="header-anchor" href="#第二步-创建-centos-8-启动介质-usb-或-dvd" aria-label="Permalink to “第二步： 创建 CentOS 8 启动介质（USB 或 DVD）”">​</a></h4><p>下载 CentOS 8 ISO 文件之后，将 ISO 文件烧录到 USB 移动硬盘或 DVD 光盘中，作为启动介质。</p><p>然后重启系统，在 BIOS 中设置为从上面烧录好的启动介质启动。</p><h4 id="第三步-选择-安装-centos-linux-8-0-选项" tabindex="-1">第三步：选择“安装 CentOS Linux 8.0”选项 <a class="header-anchor" href="#第三步-选择-安装-centos-linux-8-0-选项" aria-label="Permalink to “第三步：选择“安装 CentOS Linux 8.0”选项”">​</a></h4><p>当系统从 CentOS 8 ISO 启动介质启动之后，就可以看到以下这个界面。选择“Install CentOS Linux 8.0”（安装 CentOS Linux 8.0）选项并按回车。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Choose-Install-CentOS8.jpg" alt="Choose-Install-CentOS8"></p><h4 id="第四步-选择偏好语言" tabindex="-1">第四步：选择偏好语言 <a class="header-anchor" href="#第四步-选择偏好语言" aria-label="Permalink to “第四步：选择偏好语言”">​</a></h4><p>选择想要在 CentOS 8 <strong>安装过程</strong>中使用的语言，然后继续。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Select-Language-CentOS8-Installation.jpg" alt="Select-Language-CentOS8-Installation"></p><h4 id="第五步-准备安装-centos-8" tabindex="-1">第五步：准备安装 CentOS 8 <a class="header-anchor" href="#第五步-准备安装-centos-8" aria-label="Permalink to “第五步：准备安装 CentOS 8”">​</a></h4><p>这一步我们会配置以下内容：</p><ul><li>键盘布局</li><li>日期和时间</li><li>安装来源</li><li>软件选择</li><li>安装目标</li><li>Kdump</li></ul><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Installation-Summary-CentOS8.jpg" alt="Installation-Summary-CentOS8"></p><p>如上图所示，安装向导已经自动提供了“<ruby>键盘布局<rt>Keyboard</rt></ruby>”、“<ruby>时间和日期<rt>Time &amp; Date</rt></ruby>”、“<ruby>安装来源<rt>Installation Source</rt></ruby>”和“<ruby>软件选择<rt>Software Selection</rt></ruby>”的选项。</p><p>如果你需要修改以上设置，点击对应的图标就可以了。例如修改系统的时间和日期，只需要点击“<ruby>时间和日期<rt>Time &amp; Date</rt></ruby>”，选择正确的时区，然后点击“<ruby>完成<rt>Done</rt></ruby>”即可。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/TimeZone-CentOS8-Installation.jpg" alt="TimeZone-CentOS8-Installation"></p><p>在软件选择选项中选择安装的模式。例如“<ruby>包含图形界面<rt>Server with GUI</rt></ruby>”选项会在安装后的系统中提供图形界面，而如果想安装尽可能少的额外软件，可以选择“<ruby>最小化安装<rt>Minimal Install</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Software-Selection-CentOS8-Installation.jpg" alt="Software-Selection-CentOS8-Installation"></p><p>这里我们选择“<ruby>包含图形界面<rt>Server with GUI</rt></ruby>”，点击“<ruby>完成<rt>Done</rt></ruby>”。</p><p>Kdump 功能默认是开启的。尽管这是一个强烈建议开启的功能，但也可以点击对应的图标将其关闭。</p><p>如果想要在安装过程中对网络进行配置，可以点击“<ruby>网络与主机名<rt>Network &amp; Host Name</rt></ruby>”选项。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Networking-During-CentOS8-Installation.jpg" alt="Networking-During-CentOS8-Installation"></p><p>如果系统连接到启用了 DHCP 功能的调制解调器上，就会在启动网络接口的时候自动获取一个 IP 地址。如果需要配置静态 IP，点击“<ruby>配置<rt>Configure</rt></ruby>”并指定 IP 的相关信息。除此以外我们还将主机名设置为 “linuxtechi.com”。</p><p>完成网络配置后，点击“<ruby>完成<rt>Done</rt></ruby>”。</p><p>最后我们要配置“<ruby>安装目标<rt>Installation Destination</rt></ruby>”，指定 CentOS 8 将要安装到哪一个硬盘，以及相关的分区方式。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Installation-Destination-Custom-CentOS8.jpg" alt="Installation-Destination-Custom-CentOS8"></p><p>点击“<ruby>完成<rt>Done</rt></ruby>”。</p><p>如图所示，我为 CentOS 8 分配了 40 GB 的硬盘空间。有两种分区方案可供选择：如果由安装向导进行自动分区，可以从“<ruby>存储配置<rt>Storage Configuration</rt></ruby>”中选择“<ruby>自动<rt>Automatic</rt></ruby>”选项；如果想要自己手动进行分区，可以选择“<ruby>自定义<rt>Custom</rt></ruby>”选项。</p><p>在这里我们选择“<ruby>自定义<rt>Custom</rt></ruby>”选项，并按照以下的方式创建基于 LVM 的分区：</p><ul><li><code>/boot</code> – 2 GB (ext4 文件系统)</li><li><code>/</code> – 12 GB (xfs 文件系统)</li><li><code>/home</code> – 20 GB (xfs 文件系统)</li><li><code>/tmp</code> – 5 GB (xfs 文件系统)</li><li>Swap – 1 GB (xfs 文件系统)</li></ul><p>首先创建 <code>/boot</code> 标准分区，设置大小为 2GB，如下图所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/boot-partition-CentOS8-Installation.jpg" alt="boot-partition-CentOS8-Installation"></p><p>点击“<ruby>添加挂载点<rt>Add mount point</rt></ruby>”。</p><p>再创建第二个分区 <code>/</code>，并设置大小为 12GB。点击加号，指定挂载点和分区大小，点击“<ruby>添加挂载点<rt>Add mount point</rt></ruby>”即可。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/slash-root-partition-centos8-installation.jpg" alt="slash-root-partition-centos8-installation"></p><p>然后在页面上将 <code>/</code> 分区的分区类型从标准更改为 LVM，并点击“<ruby>更新设置<rt>Update Settings</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Change-Partition-Type-CentOS8.jpg" alt="Change-Partition-Type-CentOS8"></p><p>如上图所示，安装向导已经自动创建了一个卷组。如果想要更改卷组的名称，只需要点击“<ruby>卷组<rt>Volume Group</rt></ruby>”标签页中的“<ruby>修改<rt>Modify</rt></ruby>”选项。</p><p>同样地，创建 <code>/home</code> 分区和 <code>/tmp</code> 分区，分别将大小设置为 20GB 和 5GB，并设置分区类型为 LVM。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/home-partition-CentOS8-Installation.jpg" alt="home-partition-CentOS8-Installation"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/tmp-partition-centos8-installation.jpg" alt="tmp-partition-centos8-installation"></p><p>最后创建<ruby>交换分区<rt>Swap Partition</rt></ruby>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Swap-Partition-CentOS8-Installation.jpg" alt="Swap-Partition-CentOS8-Installation"></p><p>点击“<ruby>添加挂载点<rt>Add mount point</rt></ruby>”。</p><p>在完成所有分区设置后，点击“<ruby>完成<rt>Done</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Choose-Done-after-manual-partition-centos8.jpg" alt="Choose-Done-after-manual-partition-centos8"></p><p>在下一个界面，点击“<ruby>应用更改<rt>Accept changes</rt></ruby>”，以上做的更改就会写入到硬盘中。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Accept-changes-CentOS8-Installation.jpg" alt="Accept-changes-CentOS8-Installation"></p><h4 id="第六步-选择-开始安装" tabindex="-1">第六步：选择“开始安装” <a class="header-anchor" href="#第六步-选择-开始安装" aria-label="Permalink to “第六步：选择“开始安装””">​</a></h4><p>完成上述的所有更改后，回到先前的安装概览界面，点击“<ruby>开始安装<rt>Begin Installation</rt></ruby>”以开始安装 CentOS 8。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Begin-Installation-CentOS8.jpg" alt="Begin-Installation-CentOS8"></p><p>下面这个界面表示安装过程正在进行中。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Installation-progress-centos8.jpg" alt="Installation-progress-centos8"></p><p>要设置 root 用户的口令，只需要点击 “<ruby>root 口令<rt>Root Password</rt></ruby>”选项，输入一个口令，然后点击“<ruby>创建用户<rt>User Creation</rt></ruby>”选项创建一个本地用户。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Root-Password-CentOS8-Installation.jpg" alt="Root-Password-CentOS8-Installation"></p><p>填写新创建的用户的详细信息。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Local-User-Details-CentOS8.jpg" alt="Local-User-Details-CentOS8"></p><p>在安装完成后，安装向导会提示重启系统。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/CentOS8-Installation-Progress.jpg" alt="CentOS8-Installation-Progress"></p><h4 id="第七步-完成安装并重启系统" tabindex="-1">第七步：完成安装并重启系统 <a class="header-anchor" href="#第七步-完成安装并重启系统" aria-label="Permalink to “第七步：完成安装并重启系统”">​</a></h4><p>安装完成后要重启系统。只需点击“<ruby>重启<rt>Reboot</rt></ruby>”按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Installation-Completed-CentOS8.jpg" alt="Installation-Completed-CentOS8"></p><p>注意：重启完成后，记得要把安装介质断开，并将 BIOS 的启动介质设置为硬盘。</p><h4 id="第八步-启动新安装的-centos-8-并接受许可协议" tabindex="-1">第八步：启动新安装的 CentOS 8 并接受许可协议 <a class="header-anchor" href="#第八步-启动新安装的-centos-8-并接受许可协议" aria-label="Permalink to “第八步：启动新安装的 CentOS 8 并接受许可协议”">​</a></h4><p>在 GRUB 引导菜单中，选择 CentOS 8 进行启动。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Grub-Boot-CentOS8.jpg" alt="Grub-Boot-CentOS8"></p><p>同意 CentOS 8 的许可证，点击“<ruby>完成<rt>Done</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Accept-License-CentOS8-Installation.jpg" alt="Accept-License-CentOS8-Installation"></p><p>在下一个界面，点击“<ruby>完成配置<rt>Finish Configuration</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Finish-Configuration-CentOS8-Installation.jpg" alt="Finish-Configuration-CentOS8-Installation"></p><h4 id="第九步-配置完成后登录" tabindex="-1">第九步：配置完成后登录 <a class="header-anchor" href="#第九步-配置完成后登录" aria-label="Permalink to “第九步：配置完成后登录”">​</a></h4><p>同意 CentOS 8 的许可证以及完成配置之后，会来到登录界面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Login-screen-CentOS8.jpg" alt="Login-screen-CentOS8"></p><p>使用刚才创建的用户以及对应的口令登录，按照提示进行操作，就可以看到以下界面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/CentOS8-Ready-Use-Screen.jpg" alt="CentOS8-Ready-Use-Screen"></p><p>点击“<ruby>开始使用 CentOS Linux<rt>Start Using CentOS Linux</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Desktop-Screen-CentOS8.jpg" alt="Desktop-Screen-CentOS8"></p><p>以上就是 CentOS 8 的安装过程，至此我们已经完成了 CentOS 8 的安装。</p><p>欢迎给我们发送评论。</p><hr>',80)),i("p",null,[t[4]||(t[4]=n("via: ",-1)),o(e,{href:"https://www.linuxtechi.com/centos-8-installation-guide-screenshots/"},{default:a(()=>[...t[3]||(t[3]=[n("https://www.linuxtechi.com/centos-8-installation-guide-screenshots/",-1)])]),_:1})]),i("p",null,[t[9]||(t[9]=n("作者：",-1)),o(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...t[5]||(t[5]=[n("Pradeep Kumar",-1)])]),_:1}),t[10]||(t[10]=n(" 选题：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[6]||(t[6]=[n("lujun9972",-1)])]),_:1}),t[11]||(t[11]=n(" 译者：",-1)),o(e,{href:"https://github.com/HankChow"},{default:a(()=>[...t[7]||(t[7]=[n("HankChow",-1)])]),_:1}),t[12]||(t[12]=n(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[n("LCTT",-1)])]),_:1}),t[16]||(t[16]=n(" 原创编译，",-1)),o(e,{href:"https://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[n("Linux中国",-1)])]),_:1}),t[17]||(t[17]=n(" 荣誉推出",-1))])])}const y=r(c,[["render",d]]);export{g as __pageData,y as default};
